import 'package:hive/hive.dart';

part 'transaction_template.g.dart';

/// A predefined transaction template.
///
/// Like [Transaction] but without [date]: a template describes a recurring
/// transaction (e.g. salary, rent, bills) that the user can apply to any
/// month.
///
/// Extends [HiveObject] for local persistence.
/// The [TypeAdapter] is generated by `hive_generator` in
/// `transaction_template.g.dart`.
///
/// Fields:
/// - [id]: unique identifier (timestamp in milliseconds)
/// - [amount]: amount in euros (always positive, the sign is given by [isIncome])
/// - [isIncome]: true = income, false = expense
/// - [category]: template category (required, chosen from [CategoryProvider])
///
/// Note: [HiveField(1)] (formerly `title`) is no longer used but is kept
/// in the adapter for backward compatibility with existing Hive data.
@HiveType(typeId: 1)
class TransactionTemplate extends HiveObject {
  @HiveField(0)
  final String id;

  @HiveField(2)
  final double amount;

  @HiveField(3)
  final bool isIncome;

  @HiveField(4)
  final String category;

  TransactionTemplate({
    required this.id,
    required this.amount,
    required this.isIncome,
    required this.category,
  });
}
